{
  "name": "oclitellmac",
  "version": "0.10.0",
  "description": "OpenCode LiteLLM Auto-Config - Automatic multi-proxy configuration with budget tracking",
  "type": "module",
  "exports": {
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "scripts": {
    "build": "bun scripts/build.ts",
    "test": "bun test",
    "typecheck": "tsc -p ."
  },
  "files": [
    "dist/"
  ],
  "keywords": [
    "opencode",
    "plugin",
    "litellm",
    "auto-config",
    "budget",
    "tui"
  ],
  "author": "Markus Rathgeb <maggu2810@mailbox.org>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/maggu2810/oclitellmac.git"
  },
  "bugs": {
    "url": "https://github.com/maggu2810/oclitellmac/issues"
  },
  "homepage": "https://github.com/maggu2810/oclitellmac#readme",
  "dependencies": {
    "xdg-basedir": "^5.1.0",
    "zod": "^3.23.0"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.5",
    "@opentui/core": "0.8.0",
    "@opentui/keymap": "0.8.0",
    "@opentui/solid": "0.8.0",
    "solid-js": "*",
    "typescript": "^5.6.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.8.0",
    "@opentui/keymap": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.0.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/keymap": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  }
}
